function toast(message){$('#toast').textContent=message;$('#toast').style.display='block';clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').style.display='none',4500)}
function status(message){$('#sync-status').textContent=message}
function openDialog(html){$('#modal').innerHTML=html;$('#modal').showModal();$('#modal').querySelector('[data-close]')?.addEventListener('click',()=>$('#modal').close())}
function cover(b){if(safeImage(b.cover))return `<div class="cover uploaded-cover"><img src="${b.cover}" alt="${esc(b.title)} 표지" loading="lazy"></div>`;return `<div class="cover ${esc(b.color)}"><small>${esc(b.au)}</small><div class="cover-title"><span class="cover-rule"></span>${esc(b.title)}</div><div class="cover-bottom">${esc(b.couple)}</div></div>`}
function actual(){return books.filter(b=>!b.sample)}
function displayed(){return books}
async function initDB(){db=await new Promise((resolve,reject)=>{const r=indexedDB.open('galpi-library',2);r.onupgradeneeded=()=>{if(!r.result.objectStoreNames.contains('books'))r.result.createObjectStore('books',{keyPath:'key'});if(!r.result.objectStoreNames.contains('fonts'))r.result.createObjectStore('fonts')};r.onsuccess=()=>resolve(r.result);r.onerror=()=>reject(r.error)});await loadLocal()}
async function loadLocal(){const key=user?.uid||offlineOwner||'guest';const all=await new Promise((res,rej)=>{const r=db.transaction('books').objectStore('books').getAll();r.onsuccess=()=>res(r.result);r.onerror=()=>rej(r.error)});books=all.filter(b=>b.owner===key).map(b=>b.book)}
function putLocal(b,owner=user?.uid||offlineOwner||'guest'){const promise=new Promise((res,rej)=>{const t=db.transaction('books','readwrite');t.objectStore('books').put({key:owner+':'+b.id,owner,book:structuredClone(b)});t.oncomplete=res;t.onerror=()=>rej(t.error)});localWrites.add(promise);promise.finally(()=>localWrites.delete(promise)).catch(()=>{});return promise}
function recordDirty(b,ch){dirty.set(b.id+':'+(ch?.id||''),{b:{...b,chapters:b.chapters.map(c=>({id:c.id}))},ch:ch?structuredClone(ch):null,owner:user?.uid});}
async function saveBook(b,ch){b.updated=Date.now();if(ch)ch.updated=b.updated;try{await putLocal(b);status(user?'기기에 저장 · 동기화 대기':'이 브라우저에 저장됨');if(user){recordDirty(b,ch);clearTimeout(cloudTimer);cloudTimer=setTimeout(syncDirty,1800)}}catch{status('저장 실패 · 백업 필요');toast('기기 저장 공간에 문제가 있어요. 설정에서 원고를 백업해 주세요.')}}
async function syncDirty(){if(!firebase||!user||!cloudReady||syncing||!dirty.size)return;syncing=true;status('동기화 중…');let failed=false;for(const [key,entry] of [...dirty]){if(entry.owner!==user?.uid)continue;const {b,ch}=entry;const p=(async()=>{const {chapters,sample,...meta}=b;await firebase.setDoc(firebase.doc(firebase.db,'users',entry.owner,'galpiSeries',b.id),meta);if(ch)await firebase.setDoc(firebase.doc(firebase.db,'users',entry.owner,'galpiSeries',b.id,'chapters',ch.id),{...ch,order:b.chapters.findIndex(c=>c.id===ch.id)})})();cloudWrites.add(p);try{await p;if(dirty.get(key)===entry)dirty.delete(key)}catch(e){failed=true;status('기기 저장됨 · 클라우드 연결 확인 필요');toast(firebaseError(e));break}finally{cloudWrites.delete(p)}}syncing=false;if(!failed)status(dirty.size?'동기화 대기':'Google 계정에 저장됨');if(!failed&&dirty.size)cloudTimer=setTimeout(syncDirty,1800)}
function firebaseError(e){return ({'auth/unauthorized-domain':'Firebase 인증 설정에 현재 사이트 도메인을 추가해 주세요.','auth/operation-not-allowed':'Firebase Authentication에서 Google 로그인을 활성화해 주세요.','auth/popup-blocked':'팝업이 차단됐어요. 브라우저에서 팝업을 허용해 주세요.','auth/popup-closed-by-user':'로그인 창이 닫혔어요.','permission-denied':'Firestore 보안 규칙을 확인해 주세요. 원고는 이 기기에 저장되어 있어요.','auth/network-request-failed':'네트워크 연결을 확인해 주세요.','auth/timeout':'로그인 연결 시간이 초과됐어요. Chrome이나 Safari에서 사이트를 열어 다시 시도해 주세요.','auth/operation-not-supported-in-this-environment':'외부 브라우저에서 Google 로그인을 진행해 주세요.'})[e.code]||'연결을 완료하지 못했어요. Firebase 설정과 네트워크를 확인해 주세요.'}
async function initFirebase(){try{const base='https://www.gstatic.com/firebasejs/12.4.0/';const [app,auth,fs]=await Promise.all([import(base+'firebase-app.js'),import(base+'firebase-auth.js'),import(base+'firebase-firestore.js')]);const instance=app.initializeApp({apiKey:'AIzaSyB9SWQzJrzxbT1aKquMyqz-Hvd1Ce87xZA',authDomain:'kkyareuk.firebaseapp.com',projectId:'kkyareuk',storageBucket:'kkyareuk.firebasestorage.app',messagingSenderId:'694440030853',appId:'1:694440030853:web:2b3f385d5e88977b20afec'});firebase={...auth,...fs,auth:auth.getAuth(instance),db:fs.getFirestore(instance)};const acceptAuth=async next=>{if(!next&&!navigator.onLine&&offlineOwner){status('오프라인 · 기기에 저장');return}authBusy=true;$('#app').inert=true;await flush();user=next;offlineOwner=null;if(next)localStorage.setItem('galpi-last-owner',next.uid);else localStorage.removeItem('galpi-last-owner');cloudReady=false;dirty.clear();await loadLocal();$('#account-name').innerHTML=next?`${esc(next.displayName||'나의 계정')}<small>Google 계정 연결됨</small>`:'Google로 로그인<small>나의 이야기를 안전하게</small>';if(next){status('내 서재 불러오는 중…');try{const snap=await fs.getDocs(fs.collection(firebase.db,'users',next.uid,'galpiSeries'));const remote=await Promise.all(snap.docs.map(async d=>{const chapters=await fs.getDocs(fs.collection(firebase.db,'users',next.uid,'galpiSeries',d.id,'chapters'));return {...d.data(),id:d.id,chapters:chapters.docs.map(c=>({...c.data(),id:c.id})).sort((a,b)=>(a.order||0)-(b.order||0))}}));for(const r of remote){const local=books.find(b=>b.id===r.id);if(!local){books.push(r);await putLocal(r)}else{const merged={...(local.updated>r.updated?local:r),chapters:[...r.chapters]};for(const c of local.chapters){const n=merged.chapters.findIndex(x=>x.id===c.id);if(n<0)merged.chapters.push(c);else if(c.updated>merged.chapters[n].updated)merged.chapters[n]=c}books[books.indexOf(local)]=merged;await putLocal(merged)}}cloudReady=true;for(const b of books){const r=remote.find(x=>x.id===b.id);if(!r||b.updated>r.updated)recordDirty(b);for(const ch of b.chapters){const c=r?.chapters.find(x=>x.id===ch.id);if(!c||ch.updated>c.updated)recordDirty(b,ch)}}status('Google 계정에 연결됨');void syncDirty()}catch(e){status('기기 저장 모드 · 연결 확인 필요');toast(firebaseError(e))}}else status('이 브라우저에 저장');authBusy=false;$('#app').inert=false;route()};firebase.refresh=()=>acceptAuth(firebase.auth.currentUser);auth.onAuthStateChanged(firebase.auth,acceptAuth)}catch{status('오프라인 · 이 브라우저에 저장');toast('Google 연결을 불러오지 못했어요. 기기 저장으로 계속 사용할 수 있습니다.')}}
async function login(){if(!firebase){toast('Google 연결을 준비 중이에요. 잠시 후 다시 눌러 주세요.');return}try{status('Google 로그인 창을 확인해 주세요');const provider=new firebase.GoogleAuthProvider();provider.setCustomParameters({prompt:'select_account'});const result=firebase.signInWithPopup(firebase.auth,provider);void flush();await result}catch(e){status('로그인 미완료 · 설정에서 다시 시도');toast(firebaseError(e))}}
async function flush(){clearTimeout(saveTimer);saveTimer=null;if(pendingEdit&&currentBook&&currentChapter&&page==='edit'){pendingEdit=false;await saveBook(currentBook,currentChapter);}await Promise.allSettled([...localWrites]);void syncDirty()}
function card(b){return `<button class="book-card" data-book="${esc(b.id)}">${cover(b)}<h3>${esc(b.title)}</h3><div class="meta">${aiBadge(b)}<span>${esc(b.couple)}</span><span>·</span><span>${esc(b.au)}</span></div><div class="book-progress">${b.chapters.length}화 <span>· ${b.sample?'미리보기 작품':esc(b.status)}</span></div></button>`}
function bindBooks(){$$('[data-book]').forEach(el=>el.onclick=()=>location.hash='series/'+el.dataset.book)}
function $$(s){return [...document.querySelectorAll(s)]}
function library(){
 const all=displayed();
 const list=all.filter(b=>(filter==='전체'||b.au===filter)&&(coupleFilter==='전체'||b.couple===coupleFilter)&&[b.title,b.couple,b.au,b.description].join(' ').toLowerCase().includes(query.toLowerCase()));
 list.sort((a,b)=>sortMode==='title'?a.title.localeCompare(b.title,'ko'):b.updated-a.updated);
 $('#app').innerHTML=`<div class="page-heading"><div><p class="eyebrow">갈피 / 개인 서재</p><h1>서재</h1><p class="sub">시리즈와 회차를 관리합니다.</p></div><button class="btn primary" id="new-series">＋ 새 시리즈</button></div><div class="section-heading"><h2>시리즈 <span class="count">${actual().length}</span></h2><div class="shelf-heading"><select id="sort" aria-label="정렬"><option value="recent" ${sortMode==='recent'?'selected':''}>최근 수정순</option><option value="title" ${sortMode==='title'?'selected':''}>제목순</option></select><button class="text-btn" id="continue-read">이어서 읽기 →</button></div></div><div class="filters">${['전체',...orderedAUs(all.map(b=>b.au))].map(a=>`<button class="chip ${filter===a?'active':''}" data-filter="${esc(a)}">${esc(a)}</button>`).join('')}<input class="search" id="search" aria-label="제목, 커플링, AU 검색" placeholder="제목 · 커플링 · 세계관 검색" value="${esc(query)}"></div>${!books.length?'<p class="shelf-note">새 시리즈를 만든 뒤 TXT 파일을 가져오거나 직접 작성할 수 있습니다.</p>':''}${coupleFilter!=='전체'?`<p class="sub">${esc(coupleFilter)} <button class="text-btn" id="clear-couple">분류 해제 ×</button></p>`:''}<div class="books">${list.map(card).join('')||'<div class="empty">이 조건에 맞는 시리즈가 없습니다.</div>'}</div><div class="quick-note"><div><p>글쓰기 연습</p><small>고전 문장 읽기, 짧은 장면 연습, 소재 뽑기.</small></div><a class="btn small" href="#practice">연습 노트 열기 →</a></div>`;
 bindBooks();$('#new-series').onclick=newSeries;$$('[data-filter]').forEach(el=>el.onclick=()=>{filter=el.dataset.filter;library()});
 $('#search').oninput=e=>{query=e.target.value;const pos=e.target.selectionStart;library();$('#search').focus();$('#search').setSelectionRange(pos,pos)};
 $('#sort').onchange=e=>{sortMode=e.target.value;library()};$('#clear-couple')?.addEventListener('click',()=>{coupleFilter='전체';library()});
 $('#continue-read').disabled=!all.length;$('#continue-read').onclick=()=>{if(!all.length)return;const last=localStorage.getItem('galpi-last-'+(user?.uid||offlineOwner||'guest'));const bid=last?.split('/')[1];location.hash=all.some(b=>b.id===bid)?last:'series/'+all[0].id};
}
function newSeries(){seriesForm(null)}
function seriesForm(existing){
 let coverData=existing?.cover||'',imagePending=null;
 const b=existing||{title:'',couple:'크로네리',au:'원작',description:'',color:'slate',status:'연재 중'};
 openDialog(`<h2>${existing?'시리즈 수정':'시리즈 만들기'}</h2><form id="series-form" class="series-form"><label class="field">제목<input name="title" required maxlength="80" value="${esc(b.title)}" placeholder="시리즈 제목"></label><div class="form-columns"><label class="field">AU · 세계관<input name="au" required maxlength="50" value="${esc(b.au)}" list="au-list"><datalist id="au-list">${orderedAUs(['현대 AU','해리포터 AU','캠퍼스 AU',...actual().map(b=>b.au)]).map(a=>'<option>'+esc(a)+'</option>').join('')}</datalist></label><label class="field">커플링<input name="couple" required maxlength="50" value="${esc(b.couple)}"></label></div><label class="field">소개<textarea name="description" maxlength="500" placeholder="작품 소개 (선택)">${esc(b.description)}</textarea></label><div class="cover-upload"><img id="cover-preview" alt="표지 미리보기" ${coverData?'src="'+coverData+'"':'hidden'}><div><label class="field">표지 이미지<input id="cover-file" type="file" accept="image/jpeg,image/png,image/webp"></label><small>JPG · PNG · WebP, 최대 15MB. 저장 시 자동 축소됩니다.</small><button class="text-btn" type="button" id="remove-cover">이미지 제거</button></div></div><div class="form-columns"><label class="field">기본 표지 색<select name="color">${colors.map((color,i)=>'<option value="'+color+'" '+(color===b.color?'selected':'')+'>'+['그린','네이비','핑크','베이지','그레이','딥그린'][i]+'</option>').join('')}</select></label><label class="field">연재 상태<select name="status">${['연재 중','완결','잠시 쉬는 중'].map(s=>'<option '+(s===b.status?'selected':'')+'>'+s+'</option>').join('')}</select></label></div>${aiSwitch(b.ai)}<div class="dialog-actions"><button type="button" class="btn" data-close>취소</button><button class="btn primary" id="save-series">${existing?'저장':'만들기'}</button></div></form>`);
 $('#cover-file').onchange=e=>{const file=e.target.files[0];if(!file)return;const saveButton=$('#save-series'),previewImage=$('#cover-preview');saveButton.disabled=true;imagePending=imageData(file).then(data=>{coverData=data;previewImage.src=data;previewImage.hidden=false}).catch(e=>toast(e.message)).finally(()=>{saveButton.disabled=false;imagePending=null})};
 $('#remove-cover').onclick=()=>{if(imagePending)return;coverData='';$('#cover-file').value='';$('#cover-preview').hidden=true};
 $('#series-form').onsubmit=async e=>{e.preventDefault();if(imagePending)await imagePending;const data=Object.fromEntries(new FormData(e.target));for(const k of ['title','couple','au'])if(!data[k].trim())return toast('제목, AU, 커플링을 입력해 주세요.');const saved=existing||{id:uid(),chapters:[],symbol:'❧'};Object.assign(saved,data,{cover:coverData,ai:data.ai==='on'});if(!existing)books.push(saved);await saveBook(saved);$('#modal').close();if(existing)series(saved);else location.hash='series/'+saved.id};
}
function series(b){$('#app').innerHTML=`<a href="#library" class="back">← 서재로 돌아가기</a><div class="detail">${cover(b)}<div><div class="meta"><span class="tag">${esc(b.couple)}</span><span>×</span><span class="tag">${esc(b.au)}</span></div><h1>${esc(b.title)}</h1>${aiBadge(b)}<p class="sub">${esc(b.description)||'소개가 없습니다.'}</p><div class="meta">${b.chapters.length}화 · ${esc(b.status)}${b.sample?' · 미리보기 작품':''}</div><div class="actions"><button class="btn primary" id="start-read" ${!b.chapters.length?'disabled':''}>읽기</button>${!b.sample?'<button class="btn" id="add-chapter">＋ 회차 쓰기</button><button class="btn small" id="edit-series">정보 수정</button>':''}</div></div></div><div class="section-heading"><h2>회차 목록</h2><span class="sub">총 ${b.chapters.reduce((s,c)=>s+Array.from(c.text).length,0).toLocaleString()}자</span></div>${b.chapters.map((c,i)=>`<div class="chapter"><span class="chapter-number">${String(i+1).padStart(2,'0')}</span><button class="text-btn chapter-info" data-read="${c.id}"><strong>${esc(c.title)}</strong><small>${Array.from(c.text).length.toLocaleString()}자 · 약 ${Math.max(1,Math.ceil(c.text.length/500))}분</small></button>${!b.sample?`<button class="btn small" data-edit="${c.id}">편집</button>`:'<span class="meta">미리보기</span>'}</div>`).join('')||'<div class="empty">목차가 아직 비어 있어요.<br>첫 회차를 쓰거나 Claude에서 쓴 원고를 붙여 넣어 보세요.</div>'}`;$('#start-read').onclick=()=>location.hash=`read/${b.id}/${b.chapters[0].id}`;$('#add-chapter')?.addEventListener('click',async()=>{const c={id:uid(),title:`${b.chapters.length+1}화`,text:'',updated:Date.now()};b.chapters.push(c);await saveBook(b,c);location.hash=`edit/${b.id}/${c.id}`});$$('[data-read]').forEach(el=>el.onclick=()=>location.hash=`read/${b.id}/${el.dataset.read}`);$$('[data-edit]').forEach(el=>el.onclick=()=>location.hash=`edit/${b.id}/${el.dataset.edit}`);$('#edit-series')?.addEventListener('click',()=>editSeries(b))}
function editSeries(b){seriesForm(b)}
function edit(b,c){if(b.sample){toast('예시 작품입니다. 새 시리즈를 만들어 주세요.');location.hash='series/'+b.id;return}
 mountEditor($('#app'),b,c,{toast,openDialog,uploadFont,flush,changed:async chapter=>{if(chapter){await saveBook(b,chapter);return}pendingEdit=true;clearTimeout(saveTimer);saveTimer=setTimeout(async()=>{pendingEdit=false;await saveBook(b,c);if(page==='edit'&&currentChapter?.id===c.id&&$('#draft-status'))$('#draft-status').textContent=$('#sync-status').textContent},600)}});
}
function read(b,c){
 localStorage.setItem('galpi-last-'+(user?.uid||offlineOwner||'guest'),`read/${b.id}/${c.id}`);const m=marks(),key=b.id+'/'+c.id,index=b.chapters.indexOf(c);
 $('#app').innerHTML=`<div class="reader-toolbar"><a href="#series/${b.id}" class="btn small">← 목차</a><span class="meta">${index+1} / ${b.chapters.length}화</span><div>${!b.sample?`<a class="btn small" href="#edit/${b.id}/${c.id}">수정</a> `:''}<button class="btn small" id="bookmark">${m[key]?'◆ 저장됨':'◇ 책갈피'}</button> <button class="btn small" id="reader-options">보기 설정</button></div></div><div class="reader-settings" id="reader-settings" style="display:none">${stepper("font-size","크기",prefs.size,12,36,1,"px")}${stepper("line-height","행간",prefs.line,1,2.5,.1,"배")}${stepper("letter-space","자간",prefs.letter,-2,5,.1,"px")}${stepper("paragraph-space","문단 간격",prefs.paragraph,0,3,.1,"em")}<label>폰트 <select id="reader-font"><option value="author">작가 설정</option>${fontOptions(prefs.font||'author')}</select></label><button class="btn small" id="reader-upload">내 폰트 추가</button><button class="btn small" id="theme">밤 / 낮</button><label><input type="checkbox" id="reader-motion" ${prefs.motion!==false?'checked':''}> 움직임</label></div><div class="reader-layout"><article class="reader"><p class="eyebrow">${esc(b.title)} · ${index+1}화 ${aiBadge(b)}</p><h1>${esc(c.title)}</h1><div class="reader-text">원고 불러오는 중…</div><div class="reader-bottom">${index?`<a class="btn" href="#read/${b.id}/${b.chapters[index-1].id}">← 이전 화</a>`:'<span></span>'}${index<b.chapters.length-1?`<a class="btn primary" href="#read/${b.id}/${b.chapters[index+1].id}">다음 화 →</a>`:`<a class="btn" href="#series/${b.id}">목차로</a>`}</div></article><aside class="reader-toc"><strong>목차</strong>${b.chapters.map((ch,i)=>`<a class="${ch.id===c.id?'current':''}" href="#read/${b.id}/${ch.id}">${i+1}. ${esc(ch.title)}</a>`).join('')}</aside></div>`;
 $('#reader-font').value=prefs.font||'author';$('#reader-options').onclick=()=>{$('#reader-settings').style.display=$('#reader-settings').style.display==='none'?'flex':'none'};
 $('#bookmark').onclick=()=>{const current=marks();if(current[key])delete current[key];else current[key]={title:c.title,series:b.title};storeMarks(current);$('#bookmark').textContent=current[key]?'◆ 저장됨':'◇ 책갈피'};
 for(const [id,key] of [['font-size','size'],['line-height','line'],['letter-space','letter'],['paragraph-space','paragraph']])$('#'+id).onchange=e=>{prefs[key]=typography({[key]:e.target.value})[key];e.target.value=prefs[key];applyPrefs()};bindSteppers($('#reader-settings'));$('#theme').onclick=()=>{prefs.dark=!prefs.dark;applyPrefs()};
 $('#reader-font').onchange=e=>{prefs.font=e.target.value;applyPrefs()};$('#reader-upload').onclick=()=>uploadFont(()=>{prefs.font='custom';$('#reader-font').value='custom';applyPrefs()});$('#reader-motion').onchange=e=>{prefs.motion=e.target.checked;applyPrefs()};
 manuscriptJob({type:'render',text:c.text,marks:c.marks,characters:b.characters||[],markdown:true}).then(html=>{if(page==='read'&&currentChapter?.id===c.id){$('.reader-text').innerHTML=html||'아직 원고가 없습니다.';requestAnimationFrame(()=>scrollTo(0,position))}}).catch(e=>toast(e.message));
 applyPrefs();const position=Number(localStorage.getItem('galpi-position-'+(user?.uid||offlineOwner||'guest')+'-'+key)||0);requestAnimationFrame(()=>scrollTo(0,position));
}
function applyPrefs(){
 document.body.classList.toggle('dark',page==='read'&&prefs.dark);document.body.classList.toggle('motion-off',page==='read'&&prefs.motion===false);
 document.documentElement.style.setProperty('--reader-size',prefs.size+'px');document.documentElement.style.setProperty('--reader-line',prefs.line);document.documentElement.style.setProperty('--reader-letter',prefs.letter+'px');document.documentElement.style.setProperty('--paragraph-gap',prefs.paragraph+'em');
 const font=prefs.font&&prefs.font!=='author'?prefs.font:currentChapter?.font||'serif';document.documentElement.style.setProperty('--reading-font',FONT_PRESETS[font]?.family||FONT_PRESETS.serif.family);
 if(page==='read'){$('.reader-text')?.classList.toggle('font-override',!!prefs.font&&prefs.font!=='author')}
 localStorage.setItem('galpi-prefs',JSON.stringify(prefs));
}
function worlds(){const all=displayed(),pairs=['전체',...new Set(all.map(b=>b.couple))],aus=orderedAUs(all.map(b=>b.au));$('#app').innerHTML=`<p class="eyebrow">커플링 × 세계관</p><h1>AU 분류</h1><p class="sub">커플링과 AU로 시리즈를 찾습니다.</p><div class="world-axis"><select id="world-couple" aria-label="커플링 선택">${pairs.map(p=>`<option ${p===coupleFilter?'selected':''}>${esc(p)}</option>`).join('')}</select><span>×</span><span class="sub">AU</span></div><div class="world-grid">${aus.map((a,i)=>{const count=all.filter(b=>b.au===a&&(coupleFilter==='전체'||b.couple===coupleFilter)).length;return `<button class="world" data-au="${esc(a)}"><span class="symbol">${symbols[i%symbols.length]}</span><h3>${esc(a)}</h3><p>${count}개의 시리즈 <span style="float:right">↗</span></p></button>`}).join('')}</div>`;$('#world-couple').onchange=e=>{coupleFilter=e.target.value;worlds()};$$('[data-au]').forEach(el=>el.onclick=()=>{filter=el.dataset.au;query='';location.hash='library'})}
function writing(){const list=actual();$('#app').innerHTML=`<div class="title-row"><div><p class="eyebrow">집필 노트</p><h1>나의 집필실</h1><p class="sub">작성한 시리즈와 회차를 수정합니다.</p></div><button class="btn primary" id="new-series">＋ 새 시리즈</button></div>${list.length?list.map(b=>`<div class="saved-row"><div><a href="#series/${b.id}">${esc(b.title)}</a><p class="meta">${esc(b.couple)} × ${esc(b.au)} · ${b.chapters.length}화</p></div><a class="btn small" href="#${b.chapters.length?'edit/'+b.id+'/'+b.chapters.at(-1).id:'series/'+b.id}">이어서 쓰기 ↗</a></div>`).join(''):'<div class="empty">아직 집필 중인 작품이 없어요.<br>새 시리즈를 만들고, 첫 회차를 시작해 보세요.</div>'}`;$('#new-series').onclick=newSeries}
function bookmarks(){const list=Object.entries(marks()).filter(([key])=>{const [b,c]=key.split('/');return displayed().some(x=>x.id===b&&x.chapters.some(ch=>ch.id===c))});$('#app').innerHTML=`<p class="eyebrow">책갈피</p><h1>책갈피</h1><p class="sub">책갈피를 꽂아 둔 회차를 모았어요.</p>${list.map(([key,m])=>`<a class="saved-row" href="#read/${key}"><div>${esc(m.title)}<p class="meta">${esc(m.series)}</p></div><span>↗</span></a>`).join('')||'<div class="empty">읽기 화면에서 ◇ 책갈피를 눌러 보세요.</div>'}`}
function exportBooks(){const blob=new Blob([JSON.stringify({format:'galpi',version:1,books:actual()},null,2)],{type:'application/json'});const a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download='galpi-backup-'+new Date().toISOString().slice(0,10)+'.json';a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000)}
function settings(){openDialog(`<h2>설정</h2><p>${user?'Google 계정: '+esc(user.email):'현재 이 브라우저에 원고를 저장하고 있어요. Google로 로그인하면 계정별 서재를 이용할 수 있습니다.'}</p><div class="notice">${user?'내 계정의 원고만 불러옵니다. 화면 위에서 클라우드 저장 상태를 확인할 수 있어요.':'브라우저 데이터를 지우기 전에 원고를 백업해 주세요. 로그인 전 쓴 원고는 로그인한 뒤 백업 가져오기로 옮길 수 있어요.'}</div><div class="actions"><button class="btn" id="google-action">${user?'로그아웃':'Google로 로그인'}</button><button class="btn" id="backup">원고 백업</button><button class="btn" id="restore">백업 가져오기</button></div><p style="margin-top:20px">회차당 최대 18만 자 · 자동 저장 0.6초<br>책갈피와 읽기 위치, 글꼴 설정은 이 기기에 보관합니다.</p><p><a href="fonts/LICENSE-KoPub.md" target="_blank">KoPubWorld 서체 이용 약관</a> · 문화체육관광부 / 한국출판인회의</p><div class="dialog-actions"><button class="btn primary" data-close>닫기</button></div>`);$('#google-action').onclick=async()=>{if(!user){await login();$('#modal').close();return}await flush();if(user){if(dirty.size&&!confirm('아직 클라우드에 저장되지 않은 원고가 있어요. 기기에는 보관됩니다. 로그아웃할까요?'))return;await firebase.signOut(firebase.auth)}else await login();$('#modal').close()};$('#backup').onclick=exportBooks;$('#restore').onclick=()=>{const input=document.createElement('input');input.type='file';input.accept='.json';input.onchange=async()=>{const file=input.files[0];if(!file)return;try{if(file.size>30000000)throw Error();const data=JSON.parse(await file.text());if(data.format!=='galpi'||!Array.isArray(data.books))throw Error();const clean=data.books.map(b=>{if(typeof b.title!=='string'||typeof b.couple!=='string'||typeof b.au!=='string'||!Array.isArray(b.chapters))throw Error();return {id:uid(),title:b.title.slice(0,80),couple:b.couple.slice(0,50),au:b.au.slice(0,50),description:String(b.description||'').slice(0,500),ai:b.ai===true,cover:safeImage(b.cover),characters:Array.isArray(b.characters)?b.characters.slice(0,6).filter(p=>/^[a-zA-Z0-9-]+$/.test(p.id)).map(p=>({id:p.id,name:String(p.name||'인물').slice(0,30),photo:safeImage(p.photo)})):[],color:colors.includes(b.color)?b.color:'sage',symbol:symbols.includes(b.symbol)?b.symbol:'❧',status:['연재 중','완결','잠시 쉬는 중'].includes(b.status)?b.status:'연재 중',updated:Date.now(),chapters:b.chapters.map(c=>{if(typeof c.text!=='string'||c.text.length>180000||typeof c.title!=='string')throw Error();return {id:uid(),title:c.title.slice(0,100),text:c.text,font:FONT_PRESETS[c.font]?c.font:'serif',marks:cleanMarks(c.marks,c.text.length),layout:typography(c.layout),width:[640,800,1000].includes(c.width)?c.width:800,padding:Math.max(16,Math.min(120,Number(c.padding)||60)),align:['left','center','right'].includes(c.align)?c.align:'left',updated:Date.now()}})}});for(const b of clean){books.push(b);await saveBook(b);for(const c of b.chapters)if(user)recordDirty(b,c)}await syncDirty();$('#modal').close();route();toast(clean.length+'개 시리즈를 새 사본으로 가져왔어요.')}catch{toast('갈피 백업 파일인지 확인해 주세요. 회차는 최대 18만 자입니다.')}};input.click()}}
let routeSequence=0;
async function route(){if(authBusy)return;const seq=++routeSequence;await flush();if(seq!==routeSequence)return;const [next,bid,cid]=location.hash.slice(1).split('/');page=next||'library';currentBook=displayed().find(b=>b.id===bid);currentChapter=currentBook?.chapters.find(c=>c.id===cid);document.body.classList.remove('dark','motion-off');document.body.classList.toggle('editing',page==='edit');$$('[data-nav]').forEach(a=>a.classList.toggle('active',a.dataset.nav===page||a.dataset.nav==='library'&&['series','read'].includes(page)||a.dataset.nav==='writing'&&page==='edit'));scrollTo(0,0);if(['series','read','edit'].includes(page)&&(!currentBook||(page!=='series'&&!currentChapter))){$('#app').innerHTML='<div class="empty">이 이야기를 찾을 수 없어요.<br><a href="#library">서재로 돌아가기 →</a></div>';return}if(page==='series')series(currentBook);else if(page==='edit')edit(currentBook,currentChapter);else if(page==='read')read(currentBook,currentChapter);else if(page==='worlds')worlds();else if(page==='writing')writing();else if(page==='bookmarks')bookmarks();else if(page==='practice')practice();else library()}
$('#account').onclick=()=>user?settings():login();$('#settings').onclick=settings;window.addEventListener('hashchange',route);let scrollTimer;window.addEventListener('scroll',()=>{if(page!=='read'||!currentBook||!currentChapter)return;const key='galpi-position-'+(user?.uid||offlineOwner||'guest')+'-'+currentBook.id+'/'+currentChapter.id;const pos=scrollY;clearTimeout(scrollTimer);scrollTimer=setTimeout(()=>localStorage.setItem(key,String(pos)),200)},{passive:true});window.addEventListener('beforeunload',e=>{if(pendingEdit&&page==='edit'){clearTimeout(saveTimer);saveTimer=null;putLocal(currentBook).catch(()=>{});}if(localWrites.size||dirty.size){e.preventDefault();e.returnValue=''}});document.addEventListener('visibilitychange',()=>{if(document.hidden)flush()});window.addEventListener('online',()=>{if(cloudReady)syncDirty();else if(firebase?.refresh)firebase.refresh();else initFirebase()});
setupInstall(openDialog,toast);
try{await initDB();await restoreFont();await route();initFirebase()}catch{status('기기 저장 사용 불가');$('#app').innerHTML='<div class="empty">브라우저의 저장소를 열 수 없어요. 일반 브라우저 창에서 다시 열어 주세요.</div>'}

function aiBadge(b){return b.ai===true?'<span class="ai-badge">AI 소설</span>':''}
function aiSwitch(value){return `<label class="check-row"><input type="checkbox" name="ai" ${value?'checked':''}><span>AI 소설 <small>작품에 작게 표시합니다</small></span></label>`}
function fontOptions(selected){return Object.entries(FONT_PRESETS).map(([key,f])=>`<option value="${key}" ${key===selected?'selected':''}>${f.name}</option>`).join('')}
async function restoreFont(){try{const buffer=await new Promise((res,rej)=>{const r=db.transaction('fonts').objectStore('fonts').get('custom');r.onsuccess=()=>res(r.result);r.onerror=()=>rej(r.error)});if(buffer){const font=new FontFace('GalpiCustom',buffer);await font.load();document.fonts.add(font)}}catch{toast('내 폰트를 불러오지 못해 기본 폰트를 사용합니다.')}}
function uploadFont(done){const input=document.createElement('input');input.type='file';input.accept='.woff2,.woff,.ttf,.otf';input.onchange=async()=>{const file=input.files[0];if(!file)return;if(file.size>5*1024*1024)return toast('폰트 파일은 5MB 이하로 선택해 주세요.');try{const buffer=await file.arrayBuffer();const font=new FontFace('GalpiCustom',buffer);await font.load();await new Promise((res,rej)=>{const t=db.transaction('fonts','readwrite');t.objectStore('fonts').put(buffer,'custom');t.oncomplete=res;t.onerror=()=>rej(t.error)});for(const f of document.fonts)if(f.family==='GalpiCustom')document.fonts.delete(f);document.fonts.add(font);done();toast('내 폰트를 이 브라우저에 저장했어요. 다른 기기에서는 다시 추가해 주세요.')}catch{toast('읽을 수 없는 폰트 파일입니다. WOFF2, WOFF, TTF, OTF를 확인해 주세요.')}};input.click()}
function practice(){mountPractice($('#app'),{owner:user?.uid||offlineOwner||'guest',toast,onUse:async h=>{const c={id:uid(),title:h.title,text:h.text,marks:[],font:'serif',updated:Date.now()};const b={id:uid(),title:h.title,couple:'미분류',au:'연습에서 시작',description:'연습 노트에서 가져온 원고',color:'butter',symbol:'❧',status:'연재 중',ai:false,chapters:[c],updated:Date.now()};books.push(b);await saveBook(b,c);location.hash='edit/'+b.id+'/'+c.id}})}
